<template>
  <q-page class="arena-page">
    <q-inner-loading :showing="loading" color="primary" /><q-banner v-if="error" rounded class="error"><template #avatar><q-icon name="error_outline"/></template>{{ error }}</q-banner>
    <template v-if="!duel">
