    </template>
    <template v-else-if="duel.status==='WAITING'"><section class="waiting"><nav><q-btn flat round icon="arrow_back" @click="leave"/><span><q-icon :name="duel.visibility==='PUBLIC'?'public':'lock_outline'"/> SALA {{ duel.visibility==='PUBLIC'?'PÚBLICA':'PRIVADA' }}</span><q-space/><q-chip v-if="duel.visibility==='PRIVATE'" color="deep-purple" text-color="white" icon="key">{{ duel.code }}</q-chip></nav><header class="wait-hero"><div><p class="live"><i/> LOBBY DO DUELO</p><h1>Prepare sua estratégia.</h1><p>Selecione os assuntos em que você quer desafiar seus adversários.</p></div><div class="count"><strong>{{ duel.players.length }}</strong><span>de {{ duel.maxPlayers }}<br>jogadores</span></div></header><div class="waiting-grid"><q-card flat><q-card-section><p class="kicker">SEUS ASSUNTOS</p><h2>Onde você quer brilhar?</h2><p class="muted">Escolha {{ duel.subjectsPerPlayer }} assunto(s) para confirmar sua prontidão.</p><SubjectTreeSelect v-model="selectedSubjects" :options="subjects" label="Selecionar assuntos"/><q-btn unelevated no-caps icon="check_circle" label="Confirmar prontidão" :disable="selectedSubjects.length!==duel.subjectsPerPlayer" @click="ready"/></q-card-section></q-card><q-card flat><q-card-section><div class="players"><div><p class="kicker">JOGADORES</p><h2>Na sala</h2></div><q-badge rounded color="primary">{{ duel.players.filter(p=>p.ready).length }} PRONTOS</q-badge></div><q-list><q-item v-for="(player,index) in duel.players" :key="player.userId"><q-item-section avatar><q-avatar :color="avatar(index)" text-color="white">{{ player.name.slice(0,1).toUpperCase() }}</q-avatar></q-item-section><q-item-section><q-item-label>{{ player.name }} <q-badge v-if="player.userId===userId" outline color="primary">VOCÊ</q-badge></q-item-label><q-item-label caption>{{ player.ready?'Pronto para duelar':'Escolhendo assuntos' }}</q-item-label></q-item-section><q-item-section side><q-icon :name="player.ready?'check_circle':'more_horiz'" :color="player.ready?'positive':'grey-5'"/></q-item-section></q-item></q-list><q-btn v-if="duel.creatorUserId===userId" unelevated no-caps class="full" icon="play_arrow" label="Iniciar duelo" :disable="!duel.players.every(p=>p.ready)" @click="start"/><q-btn v-if="duel.creatorUserId===userId" flat no-caps color="negative" class="center" label="Encerrar sala" @click="remove"/></q-card-section></q-card></div></section></template>
